import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.Arrays;
import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.ArrayList;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskF solver = new TaskF();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskF {
        int MAX = (int) (1e9);

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int N = in.nextInt();
            int k = in.nextInt();
            ArrayList<int[]> interval = new ArrayList<>();
            for (int i = 0; i < k; i++) {
                interval.add(new int[]{in.nextInt(), in.nextInt()});
            }
            interval.add(new int[]{2 * N, 2 * N});
            int cur = 0;
            SegmentTree[] dp = new SegmentTree[2]; //how many sides are fried on the front, 0 is currently on front, 1 is currently on back
            dp[0] = new SegmentTree(N + 1);
            dp[1] = new SegmentTree(N + 1);
            dp[0].assign(0, 0);
            for (int i = 0; i < interval.size(); i++) {
                for (int j = N; j >= 0; j--) {
                    dp[0].assign(j, dp[0].getVal(j - (interval.get(i)[0] - cur)));
                }
                cur = interval.get(i)[1];
                int sz = interval.get(i)[1] - interval.get(i)[0];
                for (int j = N; j >= 0; j--) {
                    int[] put = new int[2];
                    for (int z = 0; z <= 1; z++) {
                        int twoSwaps = dp[z].query(j - sz, j);
                        int oneSwap = dp[(z + 1) % 2].query(j - sz, j);
                        int noSwap;
                        if (z == 1) {
                            noSwap = dp[z].getVal(j);
                        } else {
                            noSwap = dp[z].getVal(j - sz);
                        }
                        put[z] = Math.min(twoSwaps + 2, Math.min(oneSwap + 1, noSwap));
                    }
                    dp[0].assign(j, put[0]);
//                out.println(j + " " + put[0] + " " + put[1]);
                    dp[1].assign(j, put[1]);
                }
            }
            int ans = Math.min(dp[0].query(N, N), dp[1].query(N, N));
            if (ans >= MAX) {
                out.println("Hungry");
            } else {
                out.println("Full");
                out.println(ans);
            }
        }

        class SegmentTree {
            int[] tree;
            int[] arr;
            int size = 0;

            public SegmentTree(int N) {
                tree = new int[4 * N];
                arr = new int[N];
                Arrays.fill(arr, MAX);
                size = N;
                for (int i = 0; i < 4 * N; i++) {
                    tree[i] = MAX;
                }
            }

            public int query(int l, int r) {
                if (r < 0) {
                    return MAX;
                }
                return queryUtil(1, 0, size - 1, Math.max(0, l), r);
            }

            public int queryUtil(int n, int tl, int tr, int l, int r) {
                //node number, cur range of node, cur range of query
                if (l > r) {
                    return MAX;
                }
                if (tl == l && tr == r) {
                    return tree[n];
                }
                int tm = (tl + tr) / 2;
                return Math.min(queryUtil(2 * n, tl, tm, l, Math.min(r, tm)), queryUtil(2 * n + 1, tm + 1, tr, Math.max(tm + 1, l), r));
            }

            public void assign(int n, int val) {
                arr[n] = val;
                int tl = 0;
                int tr = size - 1;
                int a = 1;
                while (tl < tr) {
                    int tm = (tl + tr) >> 1;
                    if (n <= tm) {
                        tr = tm;
                        a = 2 * a;
                    } else {
                        tl = tm + 1;
                        a = 2 * a + 1;
                    }
                }
                tree[a] = val;
                a >>= 1;
                while (a > 0) {
                    tree[a] = Math.min(tree[2 * a], tree[2 * a + 1]);
                    a >>= 1;
                }
            }

            int getVal(int i) {
                if (i < 0) {
                    return MAX;
                }
                return arr[i];
            }

        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}


